  0%, 100% {
    filter: drop-shadow(0 0 6px rgba(250, 141, 196, 0.44)) drop-shadow(0 1px 2px rgba(18, 2, 10, 0.9));
  }
  50% {
    filter: drop-shadow(0 0 12px rgba(255, 174, 218, 0.72)) drop-shadow(0 1px 2px rgba(18, 2, 10, 0.92));
  }
}

