  from { transform: translate3d(-50%, 0, 0); opacity: 1; }
  to { transform: translate3d(-50%, -44px, 0); opacity: 0; }
}
@keyframes pmFrameDownPartOut {
  from { transform: translate3d(-50%, 0, 0); opacity: 1; }
  to { transform: translate3d(-50%, 44px, 0); opacity: 0; }
}
@keyframes pmFadeOutFast {
  from { opacity: 1; }
  to { opacity: 0; }
}
@keyframes pmSettingsSlideUp {
  from { transform: translate3d(0, 48px, 0); opacity: 0; }
  to { transform: translate3d(0, 0, 0); opacity: 1; }
}
@keyframes pmSettingsSlideDown {
  from { transform: translate3d(0, 0, 0); opacity: 1; }
  to { transform: translate3d(0, 48px, 0); opacity: 0; }
}
@keyframes pmTabCrossFade {
  from { transform: translate3d(0, 6px, 0); opacity: 0; }
  to { transform: translate3d(0, 0, 0); opacity: 1; }
}

.settings-modal-container[data-pm-settings="enabled"][data-pm-scene="menu"]::before {
